int* intersection(int arr1[], int n, int arr2[], int m, int* returnSize) {
    int* res = (int*)malloc(sizeof(int) * (n < m ? n : m));
    int k = 0;
    for (int i = 0; i < n; i++) {
        int found = 0;
        for (int j = 0; j < m; j++) {
            if (arr1[i] == arr2[j]) {
                found = 1;
                break;
            }
        }
        if (found) {
            int duplicate = 0;
            for (int p = 0; p < k; p++) {
                if (res[p] == arr1[i]) {
                    duplicate = 1;
                    break;
                }
            }
            if (!duplicate) res[k++] = arr1[i];
        }
    }
    *returnSize = k;
    return res;
}
int main() {
    int arr1[] = {1, 2, 2, 3};
    int n = 4;
    int arr2[] = {2, 3, 4};
    int m = 3;
    int size;
    int* res = intersection(arr1, n, arr2, m, &size);
