    int i = len - 1, j;
    while (i >= 0) {
        while (i >= 0 && str[i] == ' ') i--;
        if (i < 0) break;
        j = i;
        while (j >= 0 && str[j] != ' ') j--;
        int wordLen = i - j;
        strncat(result, str + j + 1, wordLen);
        strcat(result, " ");
        i = j;
