void compressString(char str[]) {
    char result[101] = "";
    int len = strlen(str);
    int i = 0;
    while (i < len) {
        char ch = str[i];
        int count = 1;
        while (i + 1 < len && str[i+1] == ch) {
            count++;
            i++;
        }
        result[strlen(result)] = ch;
        if (count > 1) {
            char cntStr[10];
            sprintf(cntStr, "%d", count);
            strcat(result, cntStr);
        }
        i++;
    }
    strcpy(str, result);
}
