#include <stdio.h>

int main() {
    int n, target;
    int arr[100];
    int found = 0;

    // 输入数组长度
    scanf("%d", &n);
    // 输入数组元素
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }
    // 输入目标值
    scanf("%d", &target);

    // 对数组进行排序（冒泡排序，简单实现）
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1 - i; j++) {
            if (arr[j] > arr[j + 1]) {
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }

    // 双指针法找数对
    int left = 0, right = n - 1;
    while (left < right) {
        int sum = arr[left] + arr[right];
        if (sum == target) {
            // 输出数对
            printf("(%d, %d)\n", arr[left], arr[right]);
            found = 1;
            left++;
            right--;
            // 跳过重复元素，避免重复输出相同数对
            while (left < right && arr[left] == arr[left - 1]) left++;
            while (left < right && arr[right] == arr[right + 1]) right--;
        } else if (sum < target) {
            left++;
        } else {
            right--;
        }
    }

    if (!found) {
        printf("No pairs found\n");
    }

    return 0;
}

#include <stdio.h>
#include <string.h>

int main() {
    char s[1001];
    char compressed[2001];  // 压缩后的字符串，可能更长，但最大为原长两倍
    int len;

    // 输入字符串
    gets(s);  // 注意：在C11标准中gets不安全，但二级考试常用；可改用fgets，这里按考试风格
    len = strlen(s);

    int idx = 0;  // compressed的当前索引
    int i = 0;
    while (i < len) {
        char current = s[i];
        int count = 0;
        // 统计连续相同字符个数
        while (i < len && s[i] == current) {
            count++;
            i++;
        }
        // 将字符和次数写入compressed
        compressed[idx++] = current;
        // 次数可能超过9，需要处理多位数
        if (count >= 10) {
            // 将次数转换为字符串（倒序，然后反转）
            char num[10];
            int num_len = 0;
            while (count > 0) {
                num[num_len++] = (count % 10) + '0';
                count /= 10;
            }
            // 反转num
            for (int j = 0; j < num_len / 2; j++) {
                char temp = num[j];
                num[j] = num[num_len - 1 - j];
                num[num_len - 1 - j] = temp;
            }
            // 将数字字符写入compressed
            for (int j = 0; j < num_len; j++) {
                compressed[idx++] = num[j];
            }
        } else {
            compressed[idx++] = count + '0';
        }
    }
    compressed[idx] = '\0';  // 字符串结束符

    // 比较压缩后字符串长度与原字符串长度
    if (strlen(compressed) < len) {
        printf("%s\n", compressed);
    } else {
        printf("%s\n", s);
    }

    return 0;
}

#include <stdio.h>

#define MAX 100

int main() {
    int m, n, t;
    int row[MAX], col[MAX], val[MAX];  // 原矩阵三元组
    int t_row[MAX], t_col[MAX], t_val[MAX];  // 转置后三元组
    int i, j, k;

    // 输入矩阵信息
    scanf("%d %d %d", &m, &n, &t);
    for (i = 0; i < t; i++) {
        scanf("%d %d %d", &row[i], &col[i], &val[i]);
    }

    // 快速转置算法：先统计每列的非零元素个数
    int col_count[MAX] = {0};  // 原矩阵每列的非零元素个数
    for (i = 0; i < t; i++) {
        col_count[col[i]]++;
    }

    // 计算转置后每行第一个非零元素在数组中的起始位置
    int start_pos[MAX];  // 转置后矩阵每行的起始位置（按行优先）
    start_pos[1] = 0;  // 第一行从0开始
    for (i = 2; i <= n; i++) {  // 原矩阵的列变成转置后的行
        start_pos[i] = start_pos[i - 1] + col_count[i - 1];
    }

    // 遍历原三元组，填充转置后的三元组
    for (i = 0; i < t; i++) {
        int j_col = col[i];  // 原列号，即转置后的行号
        int pos = start_pos[j_col];
        t_row[pos] = col[i];  // 转置后行 = 原列
        t_col[pos] = row[i];  // 转置后列 = 原行
        t_val[pos] = val[i];
        start_pos[j_col]++;  // 更新起始位置，指向下一个位置
    }

    // 输出转置后的三元组
    printf("Transposed matrix:\n");
